import csv
import io
import re


_NUMBER = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)")


def parse_csv(raw_csv: str):
    width = 4
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        skipinitialspace=False,
        strict=False,
    )

    def normalize(record):
        if len(record) > width:
            return record[:2] + [",".join(record[2:-1]), record[-1]]
        return record + [""] * (width - len(record))

    pending = []
    for record in records:
        pending.append(record)
        if len(record) != width:
            continue
        labels = [field.strip() for field in record]
        if all(labels) and not any(
            _NUMBER.fullmatch(labels[index]) for index in (1, 3)
        ):
            return {
                "columns": record,
                "rows": [normalize(row) for row in records],
            }
        # A full-width data-like record ends the preamble search.
        break

    header_index = next(
        (i for i, row in enumerate(pending) if len(row) == width),
        None,
    )
    if header_index is None:
        header_index = next(
            (i for i, row in enumerate(pending) if any(field.strip() for field in row)),
            None,
        )
    if header_index is None:
        return {"columns": [], "rows": []}

    rows = [normalize(row) for row in pending[header_index + 1:]]
    rows.extend(normalize(row) for row in records)
    return {"columns": normalize(pending[header_index]), "rows": rows}
